-- Preview multi-store data isolation. Additive columns plus a deterministic
-- backfill to the default/oldest store for every tenant. No rows are deleted.

ALTER TABLE orders ADD COLUMN store_id TEXT;
ALTER TABLE customers ADD COLUMN store_id TEXT;
ALTER TABLE coupons ADD COLUMN store_id TEXT;
ALTER TABLE products ADD COLUMN store_id TEXT;
ALTER TABLE product_variants ADD COLUMN store_id TEXT;
ALTER TABLE transactions ADD COLUMN store_id TEXT;
ALTER TABLE whatsapp_outbox ADD COLUMN store_id TEXT;
ALTER TABLE stock_log ADD COLUMN store_id TEXT;
ALTER TABLE suppliers ADD COLUMN store_id TEXT;
ALTER TABLE wallet_log ADD COLUMN store_id TEXT;
ALTER TABLE chat_messages ADD COLUMN store_id TEXT;
ALTER TABLE purchase_orders ADD COLUMN store_id TEXT;
ALTER TABLE goods_receipts ADD COLUMN store_id TEXT;
ALTER TABLE workflows ADD COLUMN store_id TEXT;
ALTER TABLE workflow_runs ADD COLUMN store_id TEXT;
ALTER TABLE audit_log ADD COLUMN store_id TEXT;
ALTER TABLE marketing_touchpoints ADD COLUMN store_id TEXT;
ALTER TABLE cod_reconciliations ADD COLUMN store_id TEXT;
ALTER TABLE cod_reconciliation_items ADD COLUMN store_id TEXT;
ALTER TABLE approval_requests ADD COLUMN store_id TEXT;
ALTER TABLE ai_action_requests ADD COLUMN store_id TEXT;
ALTER TABLE execution_jobs ADD COLUMN store_id TEXT;
ALTER TABLE notifications ADD COLUMN store_id TEXT;
ALTER TABLE conversations ADD COLUMN store_id TEXT;
ALTER TABLE channel_messages ADD COLUMN store_id TEXT;
ALTER TABLE marketing_campaigns ADD COLUMN store_id TEXT;
ALTER TABLE campaign_daily_metrics ADD COLUMN store_id TEXT;
ALTER TABLE pos_sessions ADD COLUMN store_id TEXT;
ALTER TABLE pos_sales ADD COLUMN store_id TEXT;
ALTER TABLE pos_sale_items ADD COLUMN store_id TEXT;
ALTER TABLE supplier_invoices ADD COLUMN store_id TEXT;
ALTER TABLE supplier_payments ADD COLUMN store_id TEXT;
ALTER TABLE purchase_returns ADD COLUMN store_id TEXT;

UPDATE orders SET store_id=(SELECT id FROM stores s WHERE s.client_id=orders.client_id AND s.status='active' ORDER BY s.is_default DESC,s.created_at LIMIT 1) WHERE store_id IS NULL;
UPDATE customers SET store_id=(SELECT id FROM stores s WHERE s.client_id=customers.client_id AND s.status='active' ORDER BY s.is_default DESC,s.created_at LIMIT 1) WHERE store_id IS NULL;
UPDATE coupons SET store_id=(SELECT id FROM stores s WHERE s.client_id=coupons.client_id AND s.status='active' ORDER BY s.is_default DESC,s.created_at LIMIT 1) WHERE store_id IS NULL;
UPDATE products SET store_id=(SELECT id FROM stores s WHERE s.client_id=products.client_id AND s.status='active' ORDER BY s.is_default DESC,s.created_at LIMIT 1) WHERE store_id IS NULL;
