UPDATE whatsapp_outbox SET store_id=(SELECT id FROM stores s WHERE s.client_id=whatsapp_outbox.client_id AND s.status='active' ORDER BY s.is_default DESC,s.created_at LIMIT 1) WHERE store_id IS NULL;
UPDATE stock_log SET store_id=(SELECT id FROM stores s WHERE s.client_id=stock_log.client_id AND s.status='active' ORDER BY s.is_default DESC,s.created_at LIMIT 1) WHERE store_id IS NULL;
