DROP INDEX IF EXISTS idx_customers_client_phone;
DROP INDEX IF EXISTS idx_coupons_client_code;
DROP INDEX IF EXISTS idx_campaign_external;
DROP INDEX IF EXISTS idx_conversation_external;
DROP INDEX IF EXISTS idx_channel_message_external;
DROP INDEX IF EXISTS idx_approval_idempotency;
DROP INDEX IF EXISTS idx_execution_jobs_idempotency;
CREATE UNIQUE INDEX IF NOT EXISTS idx_customers_store_phone ON customers(client_id,store_id,phone);
CREATE UNIQUE INDEX IF NOT EXISTS idx_coupons_store_code ON coupons(client_id,store_id,code);
CREATE UNIQUE INDEX IF NOT EXISTS idx_campaign_store_external ON marketing_campaigns(client_id,store_id,platform,external_campaign_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_conversation_store_external ON conversations(client_id,store_id,channel,external_thread_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_channel_message_store_external ON channel_messages(client_id,store_id,external_message_id) WHERE external_message_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_approval_store_idempotency ON approval_requests(client_id,store_id,idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_execution_store_idempotency ON execution_jobs(client_id,store_id,idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_orders_store ON orders(client_id,store_id,date);
CREATE INDEX IF NOT EXISTS idx_products_store ON products(client_id,store_id,name);
CREATE INDEX IF NOT EXISTS idx_variants_store ON product_variants(client_id,store_id,product_id);
CREATE INDEX IF NOT EXISTS idx_stocklog_store ON stock_log(client_id,store_id,created_at);
CREATE INDEX IF NOT EXISTS idx_customers_store ON customers(client_id,store_id);
CREATE INDEX IF NOT EXISTS idx_suppliers_store ON suppliers(client_id,store_id);
CREATE INDEX IF NOT EXISTS idx_transactions_store ON transactions(client_id,store_id,date);
CREATE INDEX IF NOT EXISTS idx_po_store ON purchase_orders(client_id,store_id,order_date);
CREATE INDEX IF NOT EXISTS idx_pos_sessions_store ON pos_sessions(client_id,store_id,status,opened_at);
CREATE INDEX IF NOT EXISTS idx_pos_sales_store ON pos_sales(client_id,store_id,created_at);
CREATE INDEX IF NOT EXISTS idx_pos_items_store ON pos_sale_items(store_id,sale_id);
CREATE INDEX IF NOT EXISTS idx_campaigns_store ON marketing_campaigns(client_id,store_id,updated_at);
CREATE INDEX IF NOT EXISTS idx_campaign_metrics_store ON campaign_daily_metrics(client_id,store_id,metric_date);
CREATE INDEX IF NOT EXISTS idx_cod_store ON cod_reconciliations(client_id,store_id,created_at);
CREATE INDEX IF NOT EXISTS idx_workflows_store ON workflows(client_id,store_id,active);
CREATE INDEX IF NOT EXISTS idx_approvals_store ON approval_requests(client_id,store_id,status,requested_at);
CREATE INDEX IF NOT EXISTS idx_execution_store ON execution_jobs(client_id,store_id,status,available_at);
